export const TIPS_PAGE = [{"h": "Dhinamum (daily plan)", "p": ["Oru naalaiku 30 nimisham podhum: 15 nimisham teacher kooda class, 10 nimisham 5 pudhu words, 5 nimisham repeat sentences sathama.", "Ore neram-la pannunga (kaalai tea neram illa raathiri saapaattukku appuram). Neram fix aanaa pazhakkam aagidum.", "Oru naal miss aanaa paravaa illa. Rendu naal thodarndhu miss pannaadheenga.", "Phone-la calendar reminder vechukkonga: 'Pesu English 8:00 PM'."]}, {"h": "Pesuradhu (speaking)", "p": ["Thappa pesuradhu problem illa; pesaama irukkuradhu dhaan problem. Mudhalla pesunga, apram sari pannikkalaam.", "Tamil-la yosichu translate pannaadheenga. Chinna sentence-la direct-ah pesunga: 'I go to work.' 'I like tea.'", "Shadowing: teacher sonna sentence-a udane appadiye sathama thirumba sollunga, adhe speed, adhe style-la.", "Unga voice-a phone-la record panni kelunga. Unga thappu ungalukke theriyum.", "Veettula family-kitta oru naalaiku 5 English sentence pesunga. 'Amma, tea ready-ah?' maadhiri chinna chinnadhaa.", "Kannaadi munnaadi 2 nimisham unga pathi pesunga: peru, ooru, velai, family."]}, {"h": "Kekkuradhu (listening)", "p": ["English padam / YouTube video subtitles ON panni paarunga. Mudhalla English subtitles; Tamil subtitles vendaam.", "YouTube-la 'English conversation for beginners' nu search pannunga; 0.75x speed-la kelunga.", "Oru chinna video-va 3 thadava paarunga: mudhal thadava puriya, rendaavadhu words-ku, moonaavadhu thirumba sollavum.", "English paattu kelunga, lyrics paarththu kooda paadunga."]}, {"h": "Uchcharippu (pronunciation)", "p": ["'th' sound: naakka pallukku idaiyila vechu 'think', 'thank you'. 'tank' illa.", "'v' and 'w' veru veru: 'very' (keezh udhadu pallula), 'water' (udadu round-ah).", "'school', 'station' - munnaadi 'i' pottu 'ischool' nu sollaadheenga. 's' la aarambinga.", "-ed endings: 'worked' = workt, 'played' = playd, 'wanted' = wan-tid.", "Word stress: ho-TEL, com-PU-ter, ba-NA-na. Teacher sollumbodhu stress-a kavaninga.", "Accent maathanum nu kavalai vendaam. Clear-ah puriyura maadhiri pesinaa podhum."]}, {"h": "Words kaththukkuradhu", "p": ["Oru naalaiku 5 words podhum, aanaa adha vechu 3 sentence sollunga. 50 words oru naal-la kaththukkaadheenga.", "Words screen-la Basic mudhalla mudinga; apram Medium. Advanced-a avasarappadaadheenga.", "Pudhu word-a veettu porulgal-la ottunga: fridge-la 'fridge', kadhavula 'door'.", "Kettu kaththukkunga, paarththu illa. Ovvoru word-um listen button press panni, adhe maadhiri sollunga.", "Pazhaiya words-a vaaram oru thadava thirumba paarunga (Progress-la notebook irukku)."]}, {"h": "Grammar - romba simple-ah", "p": ["Mudhalla moonu dhaan: ippo (I eat), appo (I ate), apparam (I will eat). Idhu podhum 80% pechukku.", "Oru sentence = yaar + enna seiraanga + edha: 'I' + 'drink' + 'tea'. Idhe pattern-la 100 sentence sollunga.", "Question kekka: 'Do you...?' (ippo), 'Did you...?' (appo), 'Will you...?' (apparam).", "Grammar rule-a padikkaama, sariyaana sentence-a niraya thadava sollunga. Kaadhukku pazhagidum."]}, {"h": "Mana nilai (mindset)", "p": ["30 naal course mudinja appuram dhaan result theriyum. Oru vaaraththula compare pannaadheenga.", "Vera yaarodavum compare pannaadheenga; neththu neengaloda mattum compare pannunga.", "Pesumbodhu yaaraavadhu sirichaa, avanga problem. Neenga kaththukkitturukkeenga, avanga illa.", "'Puriyala' nu sollradhu thappu illa. Teacher-kitta adikkadi 'Puriyala' button press pannunga.", "Chinna velai-gal: oru naal 10 nimisham pesinaalum adhu win dhaan."]}];
